import fs from 'fs';
import path from 'path';

// Script to generate 312+ accurate NCTB Class 9-10 MCQs
const data = [];

// Helper to push question
function addMCQ(subject, chapter, question, options, correctIndex, explanation, difficulty = 'medium') {
  const subCode = subject.slice(0, 3).toLowerCase().replace(/[^a-z]/g, 'sub');
  const id = `${subCode}_${data.length + 1}`;
  data.push({
    id,
    subject,
    chapter,
    question,
    options,
    correctIndex,
    explanation,
    difficulty
  });
}

