addMCQ(subB2, "বাক্য প্রকরণ", "'বরষা এলে প্লাবন হয়'—এটি গঠন অনুসারে কোন প্রকারের বাক্য?", ["সরল বাক্য", "মিশ্র বা জটিল বাক্য", "যৌগিক বাক্য", "আবেগসূচক বাক্য"], 0, "যে বাক্যে একটিমাত্র কর্তা এবং একটিমাত্র সমাপিকা ক্রিয়া থাকে তাকে সরল বাক্য বলে।", "medium");
addMCQ(subB2, "বাগধারা", "'অগাধ জলের মাছ' বাগধারাটির প্রকৃত অর্থ কী?", ["খুব চালাক ব্যক্তি", "অসহায় ব্যক্তি", "বিশাল ধনী", "শত্রুভাবাপন্ন ব্যক্তি"], 0, "বাংলা বাগধারায় 'অগাধ জলের মাছ' বলতে অত্যন্ত ধূর্ত বা সুচতুর ব্যক্তিকে নির্দেশ করা হয়।", "easy");
addMCQ(subB2, "বাগধারা", "'ডুমুরের ফুল' বাগধারার অর্থ কী?", ["অদৃশ্য বা দুর্লভ বস্তু", "সৌভাগ্যবান", "ক্ষণস্থায়ী", "কপটচারী"], 0, "ডুমুরের ফুল সচরাচর চোখে পড়ে না, তাই অতি দুর্লভ ও অমিল বস্তুকে ডুমুরের ফুল বলা হয়।", "easy");
addMCQ(subB2, "বিরামচিহ্ন", "বাংলা ব্যাকরণে কোনো বাক্যে সবচেয়ে কম সময় থামতে হয় কোন চিহ্নে?", ["কমা (,) ও উদ্ধরণ চিহ্ন", "সেমিকোলন (;)", "দাঁড়ি (।)", "কোলন (:)"], 0, "কমা এবং উদ্ধরণ চিহ্নে এক বলতে যে সময় প্রয়োজন (১ সেকেন্ডের এক-চতুর্থাংশ) সেটুকু সময় থামতে হয়।", "medium");
addMCQ(subB2, "বিরামচিহ্ন", "হাইফেন (-) চিহ্নে থামার নিয়ম কী?", ["থামার প্রয়োজন নেই", "১ সেকেন্ড", "এক বলার দ্বিগুণ সময়", "অর্ধ সেকেন্ড"], 0, "হাইফেন এবং ইলেক বা লোপ চিহ্নে উচ্চারণে থামার কোনো নিয়ম বা প্রয়োজন নেই।", "medium");

// 3. English 1st Paper (ইংরেজি ১ম পত্র) - 26 MCQs
const subE1 = "English 1st Paper";
addMCQ(subE1, "Unit 1: Good Citizens", "What is the primary responsibility of a good citizen?", ["Following laws and contributing to society", "Earning maximum wealth", "Living in seclusion", "Criticizing public infrastructure"], 0, "According to Unit 1, good citizens know their rights, perform duties, respect laws, and foster societal harmony.", "easy");
addMCQ(subE1, "Unit 1: Good Citizens", "What does the word 'civic' in 'civic responsibility' mean?", ["Relating to citizens and society", "Related to wildlife", "Related to military force", "Related to monetary profits"], 0, "'Civic' pertains to a city, citizen, or citizenship duties within a civilized community.", "easy");
addMCQ(subE1, "Unit 2: Pastimes", "Which of the following is considered a healthy physical pastime?", ["Swimming and cycling", "Continuous video gaming", "Binge-watching shows", "Daydreaming without action"], 0, "Physical outdoor pastimes like swimming, walking, and cycling revitalize body and mind.", "easy");
addMCQ(subE1, "Unit 2: Pastimes", "The word 'rejuvenate' most closely means:", ["To revitalize or refresh", "To make older", "To destroy completely", "To freeze in time"], 0, "'Rejuvenate' means to make someone feel young, lively, energetic, and invigorated again.", "medium");
addMCQ(subE1, "Unit 3: Events & Festivals", "May Day is observed worldwide to commemorate:", ["The historic struggle of working-class people", "The arrival of spring season", "The foundation of the UN", "The victory of World War II"], 0, "May Day (1st May) honors the heroic sacrifices made by Chicago workers in 1886 for an 8-hour workday.", "easy");
addMCQ(subE1, "Unit 3: Events & Festivals", "What is the Bengali New Year celebration known as?", ["Pohela Boishakh", "Pohela Falgun", "Nabanna", "Ekushey February"], 0, "Pohela Boishakh marks the first day of the Bengali calendar, celebrated with traditional songs, panta-ilish, and Mongol Shobhajatra.", "easy");
addMCQ(subE1, "Unit 3: Events & Festivals", "In Bangladesh, 21st February is internationally recognized by UNESCO as:", ["International Mother Language Day", "World Peace Day", "World Literacy Day", "International Workers' Day"], 0, "UNESCO declared 21st February as International Mother Language Day in 1999 to honor the language martyrs of 1952.", "easy");
addMCQ(subE1, "Unit 3: Events & Festivals", "The Monument 'Shaheed Minar' in Dhaka commemorates the martyrs of:", ["The 1952 Language Movement", "The 1971 Liberation War", "The 1969 Mass Upsurge", "The 1966 Six-Point Movement"], 0, "The Central Shaheed Minar honors Salam, Barkat, Rafiq, Jabbar, and Shafiur who sacrificed their lives for Bangla.", "easy");
addMCQ(subE1, "Unit 5: Nature & Environment", "What is the main greenhouse gas responsible for global warming?", ["Carbon dioxide (CO2)", "Argon", "Helium", "Hydrogen"], 0, "Carbon dioxide from fossil fuel combustion traps heat in the atmosphere, creating the greenhouse effect.", "easy");
addMCQ(subE1, "Unit 5: Nature & Environment", "Deforestation directly leads to:", ["Loss of biodiversity and soil erosion", "Increase in groundwater levels", "Rapid cooling of planetary climates", "Reduction in atmospheric carbon"], 0, "Cutting down trees destroys wildlife habitats and increases greenhouse gases, causing severe environmental imbalance.", "medium");
addMCQ(subE1, "Unit 5: Nature & Environment", "What is meant by the word 'ecosystem'?", ["A biological community interacting with its physical environment", "A computer operating system", "An economic policy of a state", "A system of electrical circuits"], 0, "An ecosystem encompasses all living organisms interacting with biotic and abiotic environmental elements.", "medium");
addMCQ(subE1, "Unit 7: Climate Change", "Why is Bangladesh particularly vulnerable to climate change?", ["Low-lying delta topography and sea-level rise", "High alpine snow caps", "Extensive polar glaciers", "Lack of rivers"], 0, "As a low-lying riverine delta, rising sea levels and intense cyclones severely affect coastal regions of Bangladesh.", "medium");
addMCQ(subE1, "Unit 7: Climate Change", "What does the abbreviation 'IPCC' stand for?", ["Intergovernmental Panel on Climate Change", "International Protection of Coastal Cities", "Integrated Project for Carbon Control", "Institute of Planetary Climate Care"], 0, "The IPCC is the United Nations body for assessing the science related to climate change.", "medium");
addMCQ(subE1, "Unit 11: Power & Energy", "Which of the following is a non-renewable energy source?", ["Coal and natural gas", "Solar energy", "Wind power", "Hydroelectric energy"], 0, "Coal, petroleum, and natural gas are fossil fuels that deplete over time and cannot be renewed naturally in human timeframes.", "easy");
addMCQ(subE1, "Unit 11: Power & Energy", "Solar panels convert sunlight directly into:", ["Electrical energy", "Sound energy", "Nuclear radiation", "Hydrostatic pressure"], 0, "Photovoltaic cells inside solar panels convert photon energy from solar radiation into direct electrical current.", "easy");
addMCQ(subE1, "Vocabulary & Reading", "The antonym of the word 'abundant' is:", ["Scarce", "Plentiful", "Excessive", "Lavish"], 0, "'Abundant' means plentiful or available in large quantities; its exact opposite is 'scarce' (rare or in short supply).", "easy");
addMCQ(subE1, "Vocabulary & Reading", "Choose the correct synonym of 'perseverance':", ["Persistence", "Hesitation", "Weakness", "Lethargy"], 0, "'Perseverance' means continuous effort and determination despite difficulties or delays.", "medium");
addMCQ(subE1, "Vocabulary & Reading", "What is the meaning of the idiom 'a blessing in disguise'?", ["A good thing that seemed bad at first", "An obvious misfortune", "A religious ceremony", "A secret conspiracy"], 0, "A blessing in disguise refers to an event that appears harmful initially but brings unexpected benefits later.", "medium");
addMCQ(subE1, "Vocabulary & Reading", "Select the word with the correct spelling:", ["Accommodation", "Acommodation", "Accomodation", "Acomodation"], 0, "'Accommodation' has double 'c' and double 'm' (a-c-c-o-m-m-o-d-a-t-i-o-n).", "medium");
addMCQ(subE1, "Unit 8: World Heritage", "The Shat Gombuj Mosque is located in which district of Bangladesh?", ["Bagerhat", "Bogura", "Cumilla", "Rajshahi"], 0, "The 15th-century historic Shat Gombuj Mosque, founded by Khan Jahan Ali, is situated in Bagerhat and listed as UNESCO World Heritage.", "easy");
addMCQ(subE1, "Unit 8: World Heritage", "The Sundarbans is renowned as the home of which iconic animal?", ["Royal Bengal Tiger", "African Lion", "Snow Leopard", "Polar Bear"], 0, "The Sundarbans mangrove forest in southern Bangladesh is the largest natural habitat of the endangered Royal Bengal Tiger.", "easy");
addMCQ(subE1, "Reading Skills", "When you read a passage quickly to find a specific phone number or date, the technique is called:", ["Scanning", "Skimming", "Extensive reading", "Critical analysis"], 0, "'Scanning' is rapid reading to search for specific data or facts, whereas 'skimming' gets the general gist.", "medium");
addMCQ(subE1, "Reading Skills", "What is the main topic sentence of a paragraph usually intended to do?", ["State the central idea of the paragraph", "List minor supporting details", "Provide a humorous joke", "Conclude the entire essay"], 0, "The topic sentence introduces the main focus and controlling thought that the rest of the paragraph develops.", "easy");
addMCQ(subE1, "Unit 4: Are We Aware?", "Which term describes illnesses resulting from contaminated drinking water?", ["Water-borne diseases", "Air-borne epidemics", "Nutritional deficiencies", "Genetic disorders"], 0, "Diseases like cholera, typhoid, and diarrhea spread through contaminated water and are termed water-borne.", "easy");
addMCQ(subE1, "Unit 9: Unconventional Jobs", "Who is regarded as the pioneer of modern artistic photography in Bangladesh?", ["Shahidul Alam", "Zainul Abedin", "SM Sultan", "Qayyum Chowdhury"], 0, "Renowned photojournalist and social activist Dr. Shahidul Alam pioneered modern documentary photography.", "medium");
addMCQ(subE1, "Vocabulary & Reading", "The word 'fragile' is closest in meaning to:", ["Delicate or easily broken", "Indestructible", "Massive and heavy", "Flexible like rubber"], 0, "'Fragile' describes items that can break or shatter easily if mishandled.", "easy");

// 4. English 2nd Paper (ইংরেজি ২য় পত্র) - 26 MCQs
const subE2 = "English 2nd Paper";
addMCQ(subE2, "Tense", "He _____ here since Monday. (Choose the correct verb form)", ["has been living", "is living", "lived", "lives"], 0, "Actions that started in the past and continue into the present with 'since' require Present Perfect Continuous Tense.", "easy");
addMCQ(subE2, "Tense", "The patient had died before the doctor _____.", ["came", "comes", "had come", "was coming"], 0, "In past perfect clauses connected by 'before', the earlier action takes Past Perfect and the later action takes Past Indefinite ('came').", "easy");
addMCQ(subE2, "Tense", "When water freezes, it _____ into ice.", ["turns", "turned", "will turn", "turning"], 0, "Universal truths and scientific facts in zero conditional statements are always expressed in the Simple Present tense.", "easy");
addMCQ(subE2, "Subject-Verb Agreement", "Neither he nor his friends _____ present in the seminar yesterday.", ["were", "was", "are", "is"], 0, "When subjects are joined by 'neither...nor', the verb agrees with the closer subject ('friends' is plural, past tense = 'were').", "medium");
addMCQ(subE2, "Subject-Verb Agreement", "Slow and steady _____ the race.", ["wins", "win", "is winning", "won"], 0, "When two singular nouns together express one single idea or entity, they take a singular verb ('wins').", "easy");
addMCQ(subE2, "Subject-Verb Agreement", "The jury _____ divided in their opinions.", ["were", "was", "is", "has been"], 0, "When a collective noun functions with individual differences in mind ('in their opinions'), it takes a plural verb.", "hard");
addMCQ(subE2, "Prepositions", "He is addicted _____ gambling.", ["to", "for", "with", "at"], 0, "The adjective 'addicted' takes the appropriate preposition 'to' followed by a noun or gerund.", "easy");
addMCQ(subE2, "Prepositions", "The man died _____ cholera.", ["of", "from", "by", "for"], 0, "Dying of a specific disease takes the preposition 'of' (die of disease, die from overwork, die by poison).", "medium");
addMCQ(subE2, "Prepositions", "She is proficient _____ English grammar.", ["in", "at", "with", "on"], 0, "Appropriate preposition: 'proficient in' a subject or language, 'good at' an activity.", "easy");
addMCQ(subE2, "Voice Change", "Change into Passive: 'I know him.'", ["He is known to me.", "He is known by me.", "He was known to me.", "He is knew to me."], 0, "The verb 'know' takes the preposition 'to' instead of 'by' in the passive voice ('known to me').", "medium");
addMCQ(subE2, "Voice Change", "Change into Passive: 'Do the work.'", ["Let the work be done.", "Let do the work.", "The work should do.", "Work is done by you."], 0, "Imperative sentences starting with a verb are converted using: Let + Object + be + past participle.", "easy");
addMCQ(subE2, "Voice Change", "Change into Passive: 'Who called you?'", ["By whom were you called?", "Who were you called by?", "By who was you called?", "Whom did call you?"], 0, "'Who' in interrogative active voice becomes 'By whom' followed by auxiliary verb + object + V3.", "medium");
addMCQ(subE2, "Narration", "He said, 'I am unwell.' Change into indirect speech.", ["He said that he was unwell.", "He said that he is unwell.", "He told that he had been unwell.", "He asked if he was unwell."], 0, "Reporting verb in past tense changes present tense to corresponding past tense ('am' becomes 'was').", "easy");
addMCQ(subE2, "Narration", "She said to me, 'What is your name?'", ["She asked me what my name was.", "She asked me what was my name.", "She told me what my name is.", "She asked that what my name was."], 0, "In indirect WH-questions, the inverted word order becomes affirmative: subject ('my name') + verb ('was').", "medium");
addMCQ(subE2, "Tag Questions", "Let's go for a walk, _____?", ["shall we", "will you", "don't we", "can we"], 0, "Proposals starting with 'Let's' or 'Let us' always take the tag question 'shall we?'.", "easy");
addMCQ(subE2, "Tag Questions", "Barking dogs seldom bite, _____?", ["do they", "don't they", "does it", "didn't they"], 0, "'Seldom' is negative in meaning, so the tag question must be positive ('do they?').", "medium");
addMCQ(subE2, "Tag Questions", "Everybody likes flowers, _____?", ["don't they", "doesn't he", "do they", "aren't they"], 0, "Indefinite pronouns like 'everybody' or 'everyone' take plural pronoun 'they', so the auxiliary verb becomes 'don't they?'.", "medium");
addMCQ(subE2, "Conditionals", "If he runs fast, he _____ the train.", ["will catch", "caught", "would catch", "catches"], 0, "First conditional rule: If + Present Indefinite, Future Indefinite (Subject + will + V1).", "easy");
addMCQ(subE2, "Conditionals", "If I were a king, I _____ the poor.", ["would help", "will help", "had helped", "helped"], 0, "Second conditional for hypothetical or unreal present states: If + Subject + were/past, Subject + would + V1.", "medium");
addMCQ(subE2, "Conditionals", "Had I seen him, I _____ the message.", ["would have given", "would give", "will give", "gave"], 0, "Third conditional inversion: Had + Subject + V3 requires Subject + would have + V3 in the principal clause.", "hard");
addMCQ(subE2, "Transformation", "Transform into Negative: 'Only Allah can help us.'", ["None but Allah can help us.", "Nothing but Allah can help us.", "Not only Allah can help us.", "Nobody but Allah can help us."], 0, "'Only' referring to a person or Creator changes into 'None but' in negative sentences.", "easy");
addMCQ(subE2, "Transformation", "Transform into Complex: 'I saw a flying bird.'", ["I saw a bird which was flying.", "I saw a bird and it was flying.", "A flying bird was seen by me.", "Seeing a bird, it was flying."], 0, "Simple participial adjectives are expanded into an adjective clause ('which was flying') for complex sentences.", "medium");
addMCQ(subE2, "Transformation", "Transform into Superlative: 'No other boy in the class is as tall as Fahim.'", ["Fahim is the tallest boy in the class.", "Fahim is taller than any other boy.", "Fahim is very tall boy.", "Fahim is one of the tallest boy."], 0, "Positive with 'No other' converts to Superlative with 'the + superlative degree' (the tallest boy).", "easy");
addMCQ(subE2, "Connectors & Modifiers", "He worked hard _____ he might pass the examination.", ["so that", "lest", "in case", "unless"], 0, "'So that' denotes purpose and is followed by subject + may/might + base form of the verb.", "medium");
addMCQ(subE2, "Connectors & Modifiers", "Walk fast lest you _____ miss the train.", ["should", "would", "might", "will"], 0, "The conjunction 'lest' ('নতুবা বা পাছে ভয় হয় যে') is strictly followed by subject + 'should' + V1.", "medium");
addMCQ(subE2, "Articles", "He is _____ European gentleman.", ["a", "an", "the", "no article"], 0, "Even though 'European' begins with vowel 'E', it is pronounced with the consonant sound 'yu' (/juː/), so it takes article 'a'.", "easy");

// 5. General Math (সাধারণ গণিত) - 26 MCQs
const subGM = "সাধারণ গণিত";
addMCQ(subGM, "বাস্তব সংখ্যা", "কোনটি অমূলদ সংখ্যা?", ["√2", "√9", "0.25", "3/4"], 0, "যে সংখ্যাকে দুইটি পূর্ণসংখ্যার অনুপাতে (p/q) প্রকাশ করা যায় না তাকে অমূলদ সংখ্যা বলে। √2 এর দশমিক মান অসীম অনাবৃত।", "easy");
addMCQ(subGM, "বাস্তব সংখ্যা", "০.৩̇ (৩ এর উপর পৌনঃপুনিক) এর সাধারণ ভগ্নাংশ কোনটি?", ["১/৩", "৩/১০", "১/৯", "৩/৯৯"], 0, "০.৩̇ = ৩/৯ = ১/৩। পৌনঃপুনিক চিহ্নের জন্য নিচে একটি ৯ বসে।", "easy");
addMCQ(subGM, "সেট ও ফাংশন", "A = {1, 2, 3} সেটের উপসেট (Subset) সংখ্যা কতটি?", ["8টি", "6টি", "9টি", "16টি"], 0, "কোনো সেটের উপাদান সংখ্যা n হলে তার উপসেট সংখ্যা 2^n। এখানে n = 3, সুতরাং 2^3 = 8 টি।", "easy");
addMCQ(subGM, "সেট ও ফাংশন", "A = {2, 3}, B = {3, 4} হলে A ∩ B = কত?", ["{3}", "{2, 3, 4}", "∅", "{2, 4}"], 0, "ছেদ সেট বা Intersection (∩) হলো উভয় সেটের সাধারণ বা কমন উপাদান। এখানে কমন উপাদান কেবল 3।", "easy");
addMCQ(subGM, "বীজগাণিতিক রাশি", "a + b = 5 এবং a - b = 3 হলে, 4ab এর মান কত?", ["16", "24", "8", "34"], 0, "আমরা জানি, 4ab = (a + b)^2 - (a - b)^2 = 5^2 - 3^2 = 25 - 9 = 16।", "medium");
addMCQ(subGM, "বীজগাণিতিক রাশি", "x + 1/x = 2 হলে, x^3 + 1/x^3 এর মান কত?", ["2", "4", "6", "8"], 0, "সূত্র: (x + 1/x)^3 - 3*x*(1/x)*(x + 1/x) = 2^3 - 3*1*2 = 8 - 6 = 2।", "easy");
addMCQ(subGM, "বীজগাণিতিক রাশি", "x^2 - 5x + 6 এর উৎপাদক কোনটি?", ["(x - 2)(x - 3)", "(x + 2)(x + 3)", "(x - 1)(x - 6)", "(x + 1)(x - 6)"], 0, "মিডল টার্ম ব্রেক: x^2 - 3x - 2x + 6 = x(x - 3) - 2(x - 3) = (x - 2)(x - 3)।", "easy");
addMCQ(subGM, "সূচক ও লগারিদম", "log2(8) এর মান কত?", ["3", "4", "2", "1"], 0, "log2(8) = log2(2^3) = 3 * log2(2) = 3 * 1 = 3।", "easy");
addMCQ(subGM, "সূচক ও লগারিদম", "যেকোনো অশূন্য সংখ্যা a এর জন্য a^0 এর মান কত?", ["1", "0", "a", "অসংজ্ঞায়িত"], 0, "সূচকের মৌলিক নিয়ম অনুযায়ী, যেকোনো অশূন্য বাস্তব সংখ্যার পাওয়ার বা ঘাত শূন্য হলে তার মান 1 হয় (a^0 = 1, যেখানে a ≠ 0)।", "easy");
addMCQ(subGM, "এক চলক সমীকরণ", "2x + 6 = 14 হলে x এর মান কত?", ["4", "5", "3", "8"], 0, "2x = 14 - 6 = 8 => x = 8 / 2 = 4।", "easy");
addMCQ(subGM, "জ্যামিতি", "ত্রিভুজের তিন কোণের সমষ্টি কত ডিগ্রি?", ["১৮০°", "৩৬০°", "৯০°", "২৭০°"], 0, "ইউক্লিডীয় সমতল জ্যামিতি অনুসারে যেকোনো ত্রিভুজের তিনটি অন্তঃস্থ কোণের সমষ্টি দুই সমকোণ বা ১৮০ ডিগ্রি।", "easy");
addMCQ(subGM, "জ্যামিতি", "সমকোণী ত্রিভুজের বৃহত্তম বাহুকে কী বলে?", ["অতিভুজ", "ভূমি", "লম্ব", "মধ্যমা"], 0, "সমকোণী ত্রিভুজে সমকোণের বিপরীত বাহু সবচেয়ে বড় হয় এবং একে অতিভুজ (Hypotenuse) বলা হয়।", "easy");
addMCQ(subGM, "বৃত্ত", "অর্ধবৃত্তস্থ কোণ সর্বদা কেমন কোণ হয়?", ["এক সমকোণ (৯০°)", "সূক্ষ্মকোণ", "স্থূলকোণ", "প্রবৃদ্ধকোণ"], 0, "বৃত্তের উপপাদ্য অনুযায়ী, অর্ধবৃত্তস্থ কোণের পরিমাপ সর্বদা ৯০ ডিগ্রি বা এক সমকোণ হয়।", "medium");
addMCQ(subGM, "বৃত্ত", "বৃত্তের ব্যাস ও ব্যাসার্ধের অনুপাত কত?", ["২ : ১", "১ : ২", "π : ১", "৪ : ১"], 0, "ব্যাস হলো ব্যাসার্ধের দ্বিগুণ (d = 2r), তাই ব্যাস : ব্যাসার্ধ = 2r : r = 2 : 1।", "easy");
addMCQ(subGM, "ত্রিকোণমিতি", "sin 30° এর মান কত?", ["১/২", "√৩/২", "১/√২", "১"], 0, "ত্রিকোণমিতিক আদর্শ মান তালিকা অনুসারে sin 30° = 1/2।", "easy");
addMCQ(subGM, "ত্রিকোণমিতি", "sin^2 θ + cos^2 θ এর মান কত?", ["1", "0", "2", "tan^2 θ"], 0, "পিথাগোরাসের উপপাদ্য থেকে প্রাপ্ত মৌলিক ত্রিকোণমিতিক অভেদ হলো sin^2 θ + cos^2 θ = 1।", "easy");
addMCQ(subGM, "ত্রিকোণমিতি", "tan 45° এর মান কত?", ["1", "0", "√3", "1/√3"], 0, "সমকোণী সমদ্বিবাহু ত্রিভুজে লম্ব ও ভূমির দৈর্ঘ্য সমান হওয়ায় tan 45° = লম্ব/ভূমি = 1।", "easy");
addMCQ(subGM, "দূরত্ব ও উচ্চতা", "ভূ-রেখার সমান্তরাল রেখার উপরে যে কোণ উৎপন্ন হয় তাকে কী বলে?", ["উন্নতি কোণ", "অবনতি কোণ", "পূরক কোণ", "সম্পূরক কোণ"], 0, "ভূতলের উপরের কোনো বিন্দু ভূ-রেখার সাথে যে কোণ উৎপন্ন করে তাকে উন্নতি কোণ (Angle of Elevation) বলে।", "medium");
addMCQ(subGM, "সসীম ধারা", "1 + 3 + 5 + 7 + ... সমান্তর ধারাটির প্রথম n সংখ্যক পদের যোগফল কত?", ["n^2", "n(n + 1)/2", "n(n + 1)", "2n - 1"], 0, "প্রথম n সংখ্যক ক্রমিক বিজোড় স্বাভাবিক সংখ্যার সমষ্টি সর্বদা n^2 এর সমান হয়।", "medium");
addMCQ(subGM, "সসীম ধারা", "2, 4, 8, 16, ... গুণোত্তর ধারাটির সাধারণ অনুপাত (r) কত?", ["2", "4", "8", "1/2"], 0, "গুণোত্তর ধারায় যেকোনো পদকে তার পূর্ববর্তী পদ দিয়ে ভাগ করলে সাধারণ অনুপাত পাওয়া যায়: 4/2 = 2।", "easy");
addMCQ(subGM, "পরিমিতি", "একটি বর্গের এক বাহুর দৈর্ঘ্য 4 সে.মি. হলে এর ক্ষেত্রফল কত?", ["16 বর্গ সে.মি.", "8 বর্গ সে.মি.", "12 বর্গ সে.মি.", "24 বর্গ সে.মি."], 0, "বর্গের ক্ষেত্রফল = (বাহুর দৈর্ঘ্য)^2 = 4^2 = 16 বর্গ সেন্টিমিটার।", "easy");
addMCQ(subGM, "পরিমিতি", "বৃত্তের পরিধির সূত্র কোনটি?", ["2πr", "πr^2", "4/3 πr^3", "πr"], 0, "বৃত্তের ব্যাসার্ধ r হলে তার মোট পরিধি বা বাউন্ডারির দৈর্ঘ্য 2πr।", "easy");
addMCQ(subGM, "পরিমিতি", "একটি আয়তক্ষেত্রের দৈর্ঘ্য 6 মিটার ও প্রস্থ 4 মিটার হলে এর পরিসীমা কত?", ["20 মিটার", "24 মিটার", "10 মিটার", "48 মিটার"], 0, "পরিসীমা = ২ × (দৈর্ঘ্য + প্রস্থ) = ২ × (৬ + ৪) = ২ × ১০ = ২০ মিটার।", "medium");
addMCQ(subGM, "পরিসংখ্যান", "উপাত্তের কেন্দ্রীয় প্রবণতার পরিমাপ কয়টি?", ["৩টি", "৪টি", "২টি", "৫টি"], 0, "কেন্দ্রীয় প্রবণতার প্রধান ৩টি পরিমাপ হলো: গাণিতিক গড় (Mean), মধ্যক (Median) ও প্রচুরক (Mode)।", "easy");
addMCQ(subGM, "পরিসংখ্যান", "2, 5, 8, 5, 9, 5, 3 উপাত্তের প্রচুরক (Mode) কোনটি?", ["5", "8", "2", "9"], 0, "প্রচুরক হলো উপাত্তে সবচেয়ে বেশিবার আসা মান। এখানে 5 সর্বাধিক ৩ বার এসেছে, তাই প্রচুরক 5।", "easy");
addMCQ(subGM, "পরিসংখ্যান", "শ্রেণি ব্যবধান 30 - 39 হলে এর শ্রেণি ব্যাপ্তি (Class interval) কত?", ["10", "9", "8", "11"], 0, "শ্রেণি ব্যাপ্তি = ঊর্ধ্বসীমা - নিম্নসীমা + ১ = ৩৯ - ৩০ + ১ = ১০।", "easy");

// 6. Higher Math (উচ্চতর গণিত) - 26 MCQs
const subHM = "উচ্চতর গণিত";
addMCQ(subHM, "সেট ও ফাংশন", "f(x) = √(x - 3) ফাংশনটির ডোমেন (Domain) কোনটি?", ["[3, ∞)", "(3, ∞)", "(-∞, 3]", "R"], 0, "বর্গমূলের ভিতরের মান ঋণাত্মক হতে পারে না। তাই x - 3 ≥ 0 => x ≥ 3, অর্থাৎ ডোমেন [3, ∞)।", "medium");
addMCQ(subHM, "সেট ও ফাংশন", "কোনো অন্বয়ের ভিন্ন ভিন্ন ক্রোমজোড়ের প্রথম উপাদানগুলো নিয়ে গঠিত সেটকে কী বলে?", ["ডোমেন", "রেঞ্জ", "কোর্ডোমেন", "প্রতিবিম্ব"], 0, "অন্বয়ের ক্রোমজোড়গুলোর প্রথম উপাদানের সেট হলো ডোমেন এবং দ্বিতীয় উপাদানের সেট হলো রেঞ্জ।", "easy");
addMCQ(subHM, "বীজগণিতীয় রাশি", "P(x) কে (x - a) দ্বারা ভাগ করলে ভাগশেষ কত হবে?", ["P(a)", "P(-a)", "0", "P(0)"], 0, "ভাগশেষ উপপাদ্য (Remainder Theorem) অনুসারে P(x) বহুপদীকে (x - a) দিয়ে ভাগ করলে ভাগশেষ P(a) হয়।", "medium");
addMCQ(subHM, "বীজগণিতীয় রাশি", "x^3 - 7x + 6 বহুপদীর একটি উৎপাদক কোনটি?", ["(x - 1)", "(x + 1)", "(x - 4)", "(x + 3)"], 0, "x = 1 বসালে: 1^3 - 7(1) + 6 = 1 - 7 + 6 = 0, সুতরাং (x - 1) একটি নিশ্চিত উৎপাদক।", "medium");
addMCQ(subHM, "জ্যামিতি", "ত্রিভুজের মধ্যমাদ্বয় বা মধ্যমাত্রয় যে বিন্দুতে মিলিত হয় তাকে কী বলে?", ["ভরকেন্দ্র (Centroid)", "পরিকেন্দ্র", "অন্তঃকেন্দ্র", "লম্ববিন্দু"], 0, "ত্রিভুজের তিনটি মধ্যমার ছেদবিন্দুকে ভরকেন্দ্র বলে। ভরকেন্দ্র প্রতিটি মধ্যমাকে ২:১ অনুপাতে বিভক্ত করে।", "easy");
addMCQ(subHM, "জ্যামিতি", "অ্যাপোলোনিয়াসের উপপাদ্য ত্রিভুজের কোন উপাদান সম্পর্কিত?", ["বাহু ও মধ্যমা", "উচ্চতা ও কোণ", "ব্যাসার্ধ ও চাপ", "পরিসীমা ও ভরকেন্দ্র"], 0, "অ্যাপোলোনিয়াসের উপপাদ্য ত্রিভুজের তিন বাহু এবং মধ্যমার মধ্যকার গভীর জ্যামিতিক সম্পর্ক প্রকাশ করে।", "medium");
addMCQ(subHM, "সমীকরণ", "ax^2 + bx + c = 0 দ্বিঘাত সমীকরণের নিশ্চায়ক (Discriminant) কোনটি?", ["b^2 - 4ac", "b^2 + 4ac", "4ac - b^2", "√(b^2 - 4ac)"], 0, "দ্বিঘাত সমীকরণের মূলের প্রকৃতি নির্ধারণকারী রাশিকে নিশ্চায়ক বলা হয়, যা D = b^2 - 4ac।", "easy");
addMCQ(subHM, "সমীকরণ", "নিশ্চায়ক b^2 - 4ac = 0 হলে সমীকরণের মূলদ্বয় কেমন হবে?", ["বাস্তব ও সমান", "অবাস্তব ও অসমান", "বাস্তব ও অসমান", "মূলদ ও অমূলদ"], 0, "নিশ্চায়ক শূন্য হলে মূল দুটি বাস্তব এবং পরস্পরের সমান হয় (-b/2a)।", "medium");
addMCQ(subHM, "অসমতা", "যদি -2x < 6 হয়, তবে x এর সঠিক মান কোনটি?", ["x > -3", "x < -3", "x > 3", "x < 3"], 0, "অসমতার উভয় পক্ষকে ঋণাত্মক সংখ্যা (-2) দ্বারা ভাগ বা গুণ করলে অসমতার চিহ্ন উল্টে যায়। তাই x > -3।", "medium");
addMCQ(subHM, "দ্বিপদী বিস্তার", "(1 + x)^n এর বিস্তৃতিতে মোট পদের সংখ্যা কতটি?", ["n + 1 টি", "n টি", "2n টি", "n - 1 টি"], 0, "দ্বিপদী রাশিতে ঘাত n হলে পদের সংখ্যা সর্বদা ঘাতের চেয়ে এক বেশি অর্থাৎ (n + 1) টি হয়।", "easy");
addMCQ(subHM, "দ্বিপদী বিস্তার", "5C2 এর মান কত?", ["10", "20", "5", "15"], 0, "5C2 = (5 × 4) / (2 × 1) = 20 / 2 = 10।", "easy");
addMCQ(subHM, "স্থানাঙ্ক জ্যামিতি", "(2, 3) এবং (5, 7) বিন্দু দুইটির মধ্যবর্তী দূরত্ব কত একক?", ["5", "4", "√7", "25"], 0, "দূরত্ব d = √[(5-2)^2 + (7-3)^2] = √[3^2 + 4^2] = √[9 + 16] = √25 = 5 একক।", "medium");
addMCQ(subHM, "স্থানাঙ্ক জ্যামিতি", "(1, 2) এবং (4, 8) বিন্দু সংযোগকারী সরলরেখার ঢাল (Slope) কত?", ["2", "3", "1/2", "6"], 0, "ঢাল m = (y2 - y1) / (x2 - x1) = (8 - 2) / (4 - 1) = 6 / 3 = 2।", "medium");
addMCQ(subHM, "স্থানাঙ্ক জ্যামিতি", "x-অক্ষের সমীকরণ কোনটি?", ["y = 0", "x = 0", "y = x", "x + y = 0"], 0, "x-অক্ষের উপর অবস্থিত প্রতিটি বিন্দুর কোটি বা y-মান সর্বদা শূন্য, তাই সমীকরণ y = 0।", "easy");
addMCQ(subHM, "ত্রিকোণমিতি", "১ রেডিয়ান কোণ সমান কত ডিগ্রি (প্রায়)?", ["৫৭.৩°", "৬০°", "৪৫°", "৯০°"], 0, "১ রেডিয়ান = (১৮০ / π)° ≈ ৫৭.২৯৫৭° বা প্রায় ৫৭.৩ ডিগ্রি। রেডিয়ান একটি ধ্রুব কোণ।", "medium");
addMCQ(subHM, "ত্রিকোণমিতি", "বৃত্তচাপ s, ব্যাসার্ধ r এবং কোণ θ (রেডিয়ানে) এর সম্পর্ক কোনটি?", ["s = rθ", "s = r/θ", "s = 2πrθ", "s = θ/r"], 0, "কেন্দ্রস্থ কোণ রেডিয়ানে পরিমাপ করা হলে বৃত্তচাপের দৈর্ঘ্য s = rθ হয়।", "easy");
addMCQ(subHM, "ত্রিকোণমিতি", "sec^2 θ - tan^2 θ এর মান কত?", ["1", "0", "-1", "2"], 0, "ত্রিকোণমিতিক অভেদ অনুসারে sec^2 θ - tan^2 θ = 1।", "easy");
